// Add a CSRF token to every request htmx issues
document.body.addEventListener("htmx:configRequest", (event) => {
  const token = document.querySelector('meta[name="csrf-token"]').content;
  event.detail.headers["X-CSRF-Token"] = token;
});

// Trigger a request from plain JavaScript and swap into an existing element
htmx.ajax("GET", "/search?q=lamp", { target: "#results", swap: "innerHTML" });

// Express: response headers can retarget, reswap and notify the page
app.post("/cart/items", (req, res) => {
  res.set("HX-Trigger", "cart-updated");
  res.set("HX-Retarget", "#cart-panel");
  res.set("HX-Reswap", "outerHTML");
  res.send('<div id="cart-panel">3 items, 41.70 EUR</div>');
});

// A 422 keeps the form on screen: allow the error fragment to be swapped
document.body.addEventListener("htmx:beforeSwap", (event) => {
  if (event.detail.xhr.status === 422) {
    event.detail.shouldSwap = true;
    event.detail.isError = false;
  }
});

/* htmx adds .htmx-request to the requesting element and to the indicator */
.htmx-indicator {
  opacity: 0;
  transition: opacity 150ms ease;
}

.htmx-request .htmx-indicator,
.htmx-request.htmx-indicator {
  opacity: 1;
}

const toast = document.querySelector("#toast");

document.body.addEventListener("htmx:beforeRequest", (event) => {
  event.detail.elt.classList.add("working");
});

document.body.addEventListener("htmx:afterRequest", (event) => {
  event.detail.elt.classList.remove("working");
  if (!event.detail.successful) {
    toast.textContent = "Request failed, try again";
  }
});

// HX-Trigger: {"cart-updated": {"value": 3}} fires this handler
document.body.addEventListener("cart-updated", (event) => {
  console.log("cart now holds", event.detail.value, "items");
});

// React only when the swapped target is the cart itself
document.body.addEventListener("htmx:afterSwap", (event) => {
  if (event.detail.target.id === "cart") {
    event.detail.target.dataset.updated = "true";
  }
});
